    "Before you start": "Kabla ya kuanza",
    "Compression re-encodes video and may reduce quality. If a format cannot keep an audio, subtitle or data track, processing stops instead of silently removing it. Your original is never changed.": "Kubana video kunahusisha kusimba upya video na kunaweza kupunguza ubora. Ikiwa umbizo haliwezi kuhifadhi sauti, maneno ya chini (subtitle) au data, uchakataji husimama badala ya kuondoa vipengele hivyo kimyakimya. Faili lako la asili halibadilishwi kamwe.",
    "This browser cannot save the result as a stream, so it will temporarily use device memory. Very large videos may exceed what the browser or device can handle.": "Kivinjari hiki hakiwezi kuhifadhi matokeo kama mtiririko wa data, hivyo kitatumia kumbukumbu ya kifaa kwa muda. Video kubwa sana zinaweza kuzidi uwezo wa kivinjari au kifaa.",
    "Compress video": "Punguza ukubwa wa video",
    "Video compression progress": "Maendeleo ya kupunguza ukubwa wa video",
    "No upload. Keep this tab open while your device works.": "Hakuna upakiaji unaofanyika. Acha kichupo hiki wazi wakati kifaa chako kinafanya kazi.",
    "Video selected. Choose quality and resolution, then compress.": "Video imechaguliwa. Chagua ubora na mwonekano (resolution), kisha punguza ukubwa.",
    "Choose a video before compressing.": "Chagua video kabla ya kupunguza ukubwa wake.",
    "Choose where to save the new video…": "Chagua mahali pa kuhifadhi video mpya…",
    "Encoding video on your device. Keep this tab open…": "Inachakata video kwenye kifaa chako. Acha kichupo hiki wazi…",
    "Compressing video: {percent}%": "Inapunguza ukubwa wa video: {percent}%",
    "Video saved as a new file, {size} smaller. Your original is unchanged.": "Video imehifadhiwa kama faili jipya, dogo kwa {size}. Faili lako la asili halijabadilika.",
    "Compressed video is {size} smaller. Review it before sharing; your original is unchanged.": "Video iliyopunguzwa ukubwa ni ndogo kwa {size}. Iangalie kabla ya kuishiriki; faili lako la asili halijabadilika.",
    "This video could not be made smaller. No copy was saved; your original is unchanged. Try a lower quality or resolution.": "Video hii haikuweza kupunguzwa ukubwa. Hakuna nakala iliyohifadhiwa; faili lako la asili halijabadilika. Jaribu ubora au mwonekano wa chini zaidi.",
    "Video compression canceled. No compressed copy was kept.": "Mchakato wa kupunguza ukubwa wa video umeghairiwa. Hakuna nakala iliyopunguzwa ukubwa iliyohifadhiwa.",
    "Save was canceled. Your original video is unchanged.": "Uhifadhi umeghairiwa. Video yako ya asili haijabadilika.",
    "This video has an audio, subtitle or data track that the selected format cannot keep. No output was saved.": "Video hii ina njia ya sauti, manukuu au data ambayo umbizo lililochaguliwa haliwezi kuhifadhi. Hakuna matokeo yaliyohifadhiwa.",
    "No video track was found in this file.": "Hakuna njia ya video iliyopatikana kwenye faili hili.",
    "This browser cannot encode the selected video in that format. Try another format or browser.": "Kivinjari hiki hakiwezi kusimba video iliyochaguliwa katika umbizo hilo. Jaribu umbizo au kivinjari kingine.",
    "This browser could not process this video. Try MP4 or WebM, another output format, or a smaller resolution.": "Kivinjari hiki hakikuweza kuchakata video hii. Jaribu MP4 au WebM, umbizo lingine la matokeo, au ubora wa chini zaidi.",
