    "PDFs are processed on this device and are never uploaded. There is no fixed file-size cap; available memory and browser support are the practical limits. Choose up to 10 PDFs to merge.": "Faili za PDF huchakatwa kwenye kifaa hiki na hazipakiwi kamwe. Hakuna kikomo maalum cha ukubwa wa faili; kumbukumbu inayopatikana na uwezo wa kivinjari ndivyo vikwazo halisi. Chagua hadi faili 10 za PDF ili kuziunganisha.",
    "JPG, PNG or WebP. No fixed file-size cap. Very large images depend on device memory; output is limited to 40 megapixels.": "JPG, PNG au WebP. Hakuna kikomo maalum cha ukubwa wa faili. Picha kubwa hutegemea kumbukumbu ya kifaa; matokeo yana kikomo cha megapikseli 40.",
