    "status.ready": "status.ready",
    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG or ICO. Animated files export their first frame. Metadata is not copied.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG au ICO. Faili zenye uhuishaji hutoa fremu yake ya kwanza. Metadata hainakiliwi.",
    "Transparent areas become white. Animated images use only their first frame.": "Maeneo ya uwazi hubadilika kuwa meupe. Picha zinazosonga hutumia fremu yake ya kwanza pekee.",
    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG and ICO. Animated files export only their first frame. Output up to 40 megapixels.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG na ICO. Faili zinazosonga hutoa fremu yake ya kwanza pekee. Matokeo ya hadi megapikseli 40.",
    "Convert common image formats to JPG, PNG or WebP on your device. Up to 20 files.": "Badilisha miundo ya kawaida ya picha kuwa JPG, PNG au WebP kwenye kifaa chako. Hadi faili 20.",
    "Add up to 20 images. No fixed file-size cap; 20 megapixels per image. Large batches depend on your device memory.": "Ongeza hadi picha 20. Hakuna kikomo maalum cha ukubwa wa faili; megapikseli 20 kwa kila picha. Uchakataji wa kundi kubwa hutegemea kumbukumbu ya kifaa chako.",
    "Images converted. Animated files become a still frame; metadata is not copied.": "Picha zimebadilishwa. Faili zinazosonga hubadilika kuwa picha tuli; metadata hainakiliwi.",
    "Some files were skipped. Use a supported image format within the on-page limits.": "Baadhi ya faili zilirukwa. Tumia muundo wa picha unaokubalika ndani ya mipaka iliyowekwa kwenye ukurasa.",
    "This image could not be decoded by your browser. Try another file or browser.": "Kivinjari chako hakikuweza kusoma picha hii. Jaribu faili au kivinjari kingine.",
    "Choose a supported image format.": "Chagua muundo wa picha unaokubalika.",
    "The browser does not support the selected output format.": "Kivinjari hakiauni muundo wa matokeo uliochaguliwa.",
    "Up to 20 images · 20 megapixels per image · no fixed file-size cap. Large batches depend on your device memory.": "Hadi picha 20 · megapikseli 20 kwa kila picha · hakuna kikomo maalum cha ukubwa wa faili. Uchakataji wa kundi kubwa hutegemea kumbukumbu ya kifaa chako.",
    "Choose up to 20 images.": "Chagua hadi picha 20.",
    "AVIF and some HEIC files may depend on browser support.": "Faili za AVIF na baadhi ya faili za HEIC zinaweza kuhitaji usaidizi wa kivinjari.",
    "AVIF and some HEIC inputs depend on browser support. Animated GIF, APNG and WebP files become a still image. SVG is rasterized, not converted into an editable vector. Metadata is not copied.": "Faili za AVIF na baadhi ya faili za HEIC zinahitaji usaidizi wa kivinjari. Faili zinazosonga za GIF, APNG na WebP hubadilika kuwa picha tuli. SVG hubadilishwa kuwa picha ya kawaida (raster), si vekta inayoweza kuhaririwa. Metadata hainakiliwi.",
    "Multi-page TIFF uses only its first page. Some TIFF compression variants may not decode.": "Faili ya TIFF yenye kurasa nyingi hutumia ukurasa wake wa kwanza pekee. Baadhi ya aina za mfinyazo wa TIFF huenda zisifunguliwe (zisifanyiwe dekodi).",
    "Choose a DOCX, XLSX or PPTX file": "Chagua faili ya DOCX, XLSX au PPTX",
    "Files stay on your device. Limits: 100 MB input, 200 MB expanded data and 5,000 package parts.": "Faili hubaki kwenye kifaa chako. Vikomo: MB 100 kwa faili ya awali, MB 200 kwa data iliyopanuliwa, na sehemu 5,000 za kifurushi.",
    "This safely recompresses the Office package without rewriting its contents. Embedded photos are not recompressed, so the result may not be smaller. Signed, encrypted, macro-enabled and older Office files are not supported. Keep your original.": "Hii hufinyaza upya kifurushi cha Office kwa usalama bila kubadilisha yaliyomo. Picha zilizopachikwa hazifinyazwi upya, hivyo faili ya mwisho huenda isiwe ndogo zaidi. Faili za Office zilizotiwa saini, zilizosimbwa kwa njia fiche, zenye 'macro', au za matoleo ya zamani hazitumiki. Hifadhi faili yako ya asili.",
    "Try to reduce file size": "Jaribu kupunguza ukubwa wa faili",
    "Processing runs locally in this browser. No upload.": "Usindikaji hufanyika ndani ya kivinjari hiki. Hakuna upakiaji wa data mtandaoni.",
    "Recompressing the Office package on your device…": "Inafinyaza upya kifurushi cha Office kwenye kifaa chako…",
    "This package is already compact. No smaller download was created.": "Kifurushi hiki tayari ni kidogo. Hakuna faili ndogo zaidi iliyozalishwa kwa ajili ya kupakuliwa.",
    "A smaller copy is ready. Compare it and keep your original.": "Nakala ndogo zaidi iko tayari. Ilinganishe na uhifadhi faili yako ya asili.",
    "The file could not be safely recompressed. Your original has not changed.": "Faili haikuweza kufinyazwa upya kwa usalama. Faili yako ya asili haijabadilika.",
    "Processing canceled. Your original file is unchanged.": "Usindikaji umesitishwa. Faili yako ya asili haijabadilika.",
    "Choose a modern DOCX, XLSX or PPTX file.": "Chagua faili ya kisasa ya DOCX, XLSX au PPTX.",
    "This file is larger than the 100 MB local processing limit.": "Faili hii ni kubwa kuliko kikomo cha MB 100 cha usindikaji wa ndani ya kifaa.",
    "The expanded package exceeds the 200 MB local processing limit.": "Kifurushi kilichopanuliwa kinazidi kikomo cha MB 200 cha usindikaji wa ndani ya kifaa.",
    "Encrypted Office packages are not supported.": "Vifurushi vya Office vilivyosimbwa kwa njia fiche havitumiki.",
    "Signed or macro-enabled Office files are not supported, to avoid invalidating signatures or macros.": "Faili za Office zilizotiwa saini au zenye 'macro' hazitumiki, ili kuepuka kuharibu uhalali wa saini au 'macro' hizo.",
    "The selected file is not a valid modern Office document of that type.": "Faili iliyochaguliwa si hati halali ya kisasa ya Office ya aina hiyo.",
    "Choose an audio file": "Chagua faili ya sauti",
    "Compress audio": "Finya sauti",
    "Audio compression progress": "Maendeleo ya kufinya sauti",
    "Choose an audio or video file": "Chagua faili ya sauti au video",
    "Detect automatically": "Tambua kiotomatiki",
    "Transcribe": "Nakili sauti kuwa maandishi",
    "Transcription progress": "Maendeleo ya kunakili sauti kuwa maandishi",
    "Choose an audio file before compressing.": "Chagua faili ya sauti kabla ya kuifinya.",
    "Choose a file to transcribe.": "Chagua faili ya kunakili sauti yake kuwa maandishi.",
    "Choose where to save the compressed file…": "Chagua mahali pa kuhifadhi faili iliyofinywa…",
