    "Audio compression: {percent}%": "Kufinya sauti: {percent}%",
    "Done. The compressed copy is {size} smaller. Check the sound; your original is unchanged.": "Imekamilika. Nakala iliyofinywa ni ndogo kwa {size}. Angalia sauti; faili yako ya asili haijabadilika.",
    "No smaller audio copy was created. Your original is unchanged.": "Hakuna nakala ndogo zaidi ya sauti iliyoundwa. Faili yako ya asili haijabadilika.",
    "Processing canceled. Your original is unchanged.": "Usindikaji umeghairiwa. Faili yako ya asili haijabadilika.",
    "Saving canceled. Your original is unchanged.": "Uhifadhi umeghairiwa. Faili yako ya asili haijabadilika.",
    "Checking for audio…": "Inatafuta sauti…",
    "Downloading speech model (first use is about 43 MB)…": "Inapakua modeli ya usemi (matumizi ya mara ya kwanza yanahitaji takriban MB 43)…",
    "Downloading model: {percent}%": "Inapakua modeli: {percent}%",
    "Transcribing on your device…": "Inanakili sauti kuwa maandishi kwenye kifaa chako…",
    "Transcription complete. Review names and numbers.": "Unukuzi umekamilika. Hakiki majina na namba.",
    "No speech detected. Try clearer audio or choose a language.": "Hakuna sauti iliyogunduliwa. Jaribu sauti iliyo wazi zaidi au chagua lugha.",
    "Copied to clipboard.": "Imenakiliwa kwenye ubao wa kunakili (clipboard).",
    "Copy was blocked. Select the text and copy it manually.": "Unakili ulizuiwa. Chagua maandishi na uyanakili wewe mwenyewe.",
    "Text file downloaded.": "Faili ya maandishi imepakuliwa.",
    "This file or codec could not be processed. Try another supported format.": "Faili au kodeki hii haikuweza kuchakatwa. Jaribu umbizo lingine linalotumika.",
    "For long or high-resolution media, a desktop or laptop is recommended. Keep this tab open; speed, memory and battery depend on your device.": "Kwa faili za midia ndefu au zenye ubora wa juu, kompyuta ya mezani au ya pajani inapendekezwa. Acha kichupo hiki kikiwa wazi; kasi, kumbukumbu na betri hutegemea kifaa chako.",
    "Re-encoding can reduce sound quality or make a larger file. Your original stays unchanged.": "Kubadilisha umbizo (re-encoding) kunaweza kupunguza ubora wa sauti au kutengeneza faili kubwa zaidi. Faili yako asili haitabadilishwa.",
    "First use downloads about 58 MB of model and local engine. Your recording is not uploaded; the browser may download them again if its cache is cleared.": "Matumizi ya mara ya kwanza hupakua takriban MB 58 za modeli na injini ya ndani. Rekodi yako haipakiwi mtandaoni; kivinjari kinaweza kuzipakua tena ikiwa akiba yake (cache) itafutwa.",
    "Your file is processed locally and is not uploaded.": "Faili yako inachakatwa ndani ya kifaa na haipakiwi mtandaoni.",
