    "Supports whole numbers in bases 2 through 36. Digits 0–9 and letters A–Z represent values.": "Husaidia nambari kamili katika mifumo ya nambari (bases) kuanzia 2 hadi 36. Tarakimu 0–9 na herufi A–Z huwakilisha thamani.",
