    "Text-based PDFs can be extracted without OCR.": "Maandishi ya PDF yanayoweza kuchaguliwa yanaweza kutolewa bila OCR.",
    "Extracted text": "Maandishi yaliyotolewa",
    "Download TXT": "Pakua TXT",
    "PDF to Word": "PDF hadi Word",
