    "Convert file": "Badilisha faili",
    "Some characters need your browser fonts. In the print window, choose Save as PDF.": "Baadhi ya herufi zinahitaji fonti za kivinjari chako. Kwenye dirisha la kuchapisha, chagua \"Hifadhi kama PDF\" (Save as PDF).",
    "Choose a fillable PDF": "Chagua PDF inayoweza kujazwa",
