    "Signature drawing area": "Eneo la kuchora sahihi",
    "Clear signature": "Futa sahihi",
    "Place signature on page": "Weka sahihi kwenye ukurasa",
    "Download filled PDF": "Pakua PDF iliyojazwa",
    "Choose a PDF form to begin.": "Chagua fomu ya PDF ili uanze.",
    "Original PDF": "PDF asili",
    "Updated PDF": "PDF iliyosasishwa",
