    "Choose files or a ZIP archive": "Chagua faili au faili iliyobanwa ya ZIP (archive)",
    "Up to 200 files and 250 MB expanded data. ZIP64 and password-protected files are not supported.": "Hadi faili 200 na data iliyopanuliwa ya MB 250. Faili za ZIP64 na zile zilizolindwa kwa nenosiri hazitumiki.",
    "Files are not uploaded.": "Faili hazijapakiwa.",
