    "Start background removal": "Anza kuondoa mandharinyuma",
    "The first use loads about 6.6 MB from this site. The photo is processed on your device. A computer is recommended for large images.": "Mara ya kwanza kutumia, mfumo hupakua takriban MB 6.6 kutoka kwenye tovuti hii. Picha huchakatwa kwenye kifaa chako. Kompyuta inapendekezwa kwa picha kubwa.",
    "Transparent PNG preview": "Hakiki ya PNG yenye mandharinyuma wazi",
    "Original portrait": "Picha halisi ya wima",
    "Download transparent PNG": "Pakua PNG yenye mandharinyuma wazi",
    "Model loading": "Inapakia modeli",
    "Processing the photo locally…": "Inachakata picha kwenye kifaa chako…",
    "Choose an image first.": "Chagua picha kwanza.",
    "Ready to remove the background.": "Tayari kuondoa mandharinyuma.",
    "Portrait image must be 20 megapixels or smaller. Resize it before processing.": "Picha ya wima lazima iwe na megapikseli 20 au chini ya hapo. Badilisha ukubwa wake kabla ya kuichakata.",
    "Background removal complete. Review the edges before using the image.": "Kuondoa mandharinyuma kumekamilika. Kagua kingo kabla ya kutumia picha hiyo.",
    "WebM video": "Video ya WebM",
    "Start (seconds)": "Anza (sekunde)",
    "End (seconds, optional)": "Maliza (sekunde, hiari)",
    "End of file": "Mwisho wa faili",
    "Save large output directly to disk (supported browsers)": "Hifadhi matokeo makubwa moja kwa moja kwenye diski (vivinjari vinavyotumika)",
    "Expression": "Msemo wa kihisabati",
    "Supports arithmetic, powers, percentages, trigonometry, roots and logarithms.": "Inasaidia hesabu za kawaida, vipeo, asilimia, trigonometria, mizizi na logarithmi.",
    "Use radians (otherwise degrees)": "Tumia radiani (vinginevyo digrii)",
