    "Choose a file": "Chagua faili",
    "Office files stay on your device. Layout, formulas, charts, animations, fonts and page breaks may change. Office to PDF opens your browser’s print dialog. Use a computer for large files.": "Mafaili ya Office hubaki kwenye kifaa chako. Mpangilio, fomula, chati, uhuishaji, fonti na migawanyiko ya kurasa vinaweza kubadilika. Kipengele cha Office hadi PDF hufungua dirisha la kuchapisha la kivinjari chako. Tumia kompyuta kwa mafaili makubwa.",
    "PDF to Excel estimates rows from selectable text; it does not recreate formulas or tables. PDF to PowerPoint makes image-only slides. Scanned PDFs need OCR first.": "Kipengele cha PDF hadi Excel hukadiria safumlalo kutoka kwa maandishi yanayoweza kuchaguliwa; hakitengenezi upya fomula au majedwali. Kipengele cha PDF hadi PowerPoint hutengeneza slaidi zenye picha pekee. Faili za PDF zilizochanganuliwa (scanned) zinahitaji OCR kwanza.",
    "Office print view opened. Check it, then choose Save as PDF in the browser.": "Mwonekano wa kuchapisha wa Office umefunguliwa. Ukague, kisha uchague \"Hifadhi kama PDF\" kwenye kivinjari.",
